const escapeRegExp = (value: string) =>
  value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

const compilePhrases = (phrases: PhraseMap): CompiledPhraseMap => {
  const sortedPhrases = [...phrases].sort((a, b) => b[0].length - a[0].length);
  const entries: readonly CompiledPhrase[] = sortedPhrases.map(([from, to]) => {
    const escaped = escapeRegExp(from);
    const isWordPhrase = /^[\p{L}\p{N}]+(?:\s+[\p{L}\p{N}]+)*$/u.test(from);
    return [
      new RegExp(isWordPhrase ? `\\b${escaped}\\b` : escaped, "gi"),
      to,
      from.includes("{"),
    ] as const;
  });

  const exact = new Map<string, CompiledPhrase>();
  for (let index = 0; index < sortedPhrases.length; index += 1) {
    const source = sortedPhrases[index]?.[0];
    const entry = entries[index];
    if (source && entry && !exact.has(source.toLowerCase())) {
      exact.set(source.toLowerCase(), entry);
    }
  }

  return exact;
};

const replacePhrases = (source: string, phrases: readonly CompiledPhrase[]) => {
  let result = source;

  // Translate complete templates first, then protect interpolation tokens
  // while the glossary handles remaining words.
  for (const [pattern, replacement, hasPlaceholder] of phrases) {
    if (!hasPlaceholder) continue;
    result = result.replace(pattern, replacement);
  }

  const placeholders: string[] = [];
  result = result.replace(/\{(\w+)\}/g, (match) => {
    const token = `@@I18N_PLACEHOLDER_${placeholders.length}@@`;
    placeholders.push(match);
    return token;
  });

  for (const [pattern, replacement, hasPlaceholder] of phrases) {
    if (hasPlaceholder) continue;
    result = result.replace(pattern, replacement);
  }

  result = result.replace(
    /@@I18N_PLACEHOLDER_(\d+)@@/g,
    (_, index: string) => placeholders[Number(index)] ?? _,
  );

  return result;
};

const decodeHtmlEntities = (value: string) =>
  value
    .replace(/&apos;|&#39;/gi, "'")
    .replace(/&quot;|&#34;/gi, '"')
    .replace(/&gt;|&#62;/gi, ">")
    .replace(/&lt;|&#60;/gi, "<")
    .replace(/&amp;|&#38;/gi, "&");

const compiledIdPhrases = compilePhrases([
  ...employeeScheduleIdPhrases,
  ...idPhrases,
  ...additionalIdPhrases,
  ...auditIdPhrases,
  ...attendanceIdPhrases,
  ...summaryIdPhrases,
  ...globalIdPhrases,
  ...settingsIdPhrases,
  ...moduleIdPhrases,
  ...commonIdPhrases,
]);
const compiledZhPhrases = compilePhrases([
  ...employeeScheduleZhPhrases,
  ...zhPhrases,
  ...additionalZhPhrases,
  ...auditZhPhrases,
  ...attendanceZhPhrases,
  ...summaryZhPhrases,
  ...globalZhPhrases,
  ...settingsZhPhrases,
  ...moduleZhPhrases,
  ...commonZhPhrases,
]);
const compiledFallbackIdPhrases = compilePhrases(fallbackIdPhrases);
const compiledFallbackZhPhrases = compilePhrases(fallbackZhPhrases);
const compiledEnglishPhrases = compilePhrases(englishPhrases);
const compiledFallbackEnglishPhrases = compilePhrases(
  fallbackEnglishWordPhrases,
);
const staticSourceSet = new Set<string>(Object.values(staticTextSources));
const indonesianSourcePattern =
  /\b(?:aturan|bersama|ditolak|jika|melaporkan|akurasi|diberlakukan|lokasi|tetap|diproses|dibaca|perangkat|pengaturan|lanjutan|pilih|metode|prorata|aktif|nama|profil|konfigurasi|agar|mudah|dibedakan|cara|menghitung|gaji|proporsional|ketika|karyawan|bekerja|selama|periode|penuh|dasar|memuat|izinkan|negatif|potongan|melebihi|pendapatan|buat|versi|baru|kosongkan|berlaku|semua|cabang|membatasi|cakupan|bulan|mulai|berlakunya|gunakan|mendatang|perubahan|berikutnya|catatan|tambahan|mengenai|kebijakan|alasan|referensi|dibuat|siap|dikonfigurasi|dites|sederhana|keterangan|tambah|ubah|hapus|terapkan|kategori|sampai|tarif|simpan|batal|kembali|lanjut|belum|berstatus|pertama|melalui|salin|sudah|sumber|isi|hanya|pemerintah|kode|internal|struktur|teknis|perlu|diisi|tersedia|nomor|contoh|batas|harian|berubah|periksa|mengikuti|dikelola|wajib|pengajuan|persetujuan|pelatihan|sertifikasi|dokumen|diunduh|diperbarui|dihapus|ditemukan)\b/i;

export const translateStaticText = (source: string, locale: Locale): string => {
  const decodedSource = decodeHtmlEntities(source);
  if (locale === "en") {
    const englishPhrase = compiledEnglishPhrases.get(
      decodedSource.toLowerCase(),
    );
    if (englishPhrase) {
      return decodeHtmlEntities(replacePhrases(decodedSource, [englishPhrase]));
    }
    if (
      (!staticSourceSet.has(source) && !staticSourceSet.has(decodedSource)) ||
      !indonesianSourcePattern.test(decodedSource)
    ) {
      return decodedSource;
    }
    return decodeHtmlEntities(
      replacePhrases(decodedSource, [
        ...compiledFallbackEnglishPhrases.values(),
      ]),
    );
  }

  const phrases = locale === "id" ? compiledIdPhrases : compiledZhPhrases;
  const sourcePhrase = phrases.get(source.toLowerCase());
  const decodedPhrase = phrases.get(decodedSource.toLowerCase());
  const exactPhrase = sourcePhrase ?? decodedPhrase;
  const phraseInput = sourcePhrase ? source : decodedSource;

  if (exactPhrase) {
    return decodeHtmlEntities(replacePhrases(phraseInput, [exactPhrase]));
  }

  // The fallback glossary is deliberately limited to literals from the
  // generated static catalog. API values and identifiers therefore remain
  // untouched, while the long tail of settings copy still follows the locale.
  if (!staticSourceSet.has(source) && !staticSourceSet.has(decodedSource)) {
    return decodedSource;
  }
  const fallbackPhrases =
    locale === "id" ? compiledFallbackIdPhrases : compiledFallbackZhPhrases;
  return decodeHtmlEntities(
    replacePhrases(decodedSource, [...fallbackPhrases.values()]),
  );
};

/**
 * Localize option labels at render time while keeping their values untouched.
 * The options remain module-level constants, so no translated data is sent to
 * the API and no catalog object is rebuilt when the locale is not used.
 */
export const localizeStaticOptions = <T extends { label?: string }>(
  options: readonly T[],
  translate: (source: string) => string,
): T[] =>
  options.map((option) =>
    typeof option.label === "string"
      ? { ...option, label: translate(option.label) }
      : option,
  );
